import AVFoundation
import Foundation
import Testing
import TrimlabMedia
import TrimlabModel
@testable import TrimlabEditor

/// Main-actor stall (hang-report.md): with the live media services, a real composition in a real `PreviewEngine`
/// and real scrub players, no `AVURLAsset` may be freed on the main thread across import, peek, scrub, New Reel
/// and the model going away.
@MainActor @Suite(.serialized) struct AssetLifetimeTests {
  /// Packages/TrimlabKit/Tests/Fixtures (generated by the MediaTests fixtures script).
  static let fixtures: URL = {
    var url = URL(filePath: #filePath)
    url.deleteLastPathComponent()
    url.deleteLastPathComponent()
    return url.appending(path: "Fixtures", directoryHint: .isDirectory)
  }()

  @Test func realAssetsAreNeverFreedOnMain() async throws {
    let names = ["portrait_hevc.mov", "landscape.mp4", "noaudio.mp4", "keyframes.mp4", "sixty.mp4"]
    let urls = names.map { Self.fixtures.appending(path: $0) }
    try #require(urls.allSatisfy { FileManager.default.fileExists(atPath: $0.path) }, "fixtures missing")
    let root = FileManager.default.temporaryDirectory.appending(path: "trimlab2-assetlife-\(UUID())")
    defer { try? FileManager.default.removeItem(at: root) }
    let deaths = AssetDeaths()
    let made = AssetDeaths()  // `total` counts the assets handed out
    let media = LiveMediaServices(cache: MediaCache(root: root), logTail: nil) { url, precise in
      made.total.add(1, ordering: .relaxed)
      return TrackedAsset(url: url, deaths: deaths, precise: precise)
    }
    var model: EditorModel? = EditorModel(
      platform: StubPlatform(), media: media, store: MemoryProjectStore(),
      prefs: Prefs(), clock: ManualClock(), preview: PreviewEngine())

    await model!.importURLs(urls, at: nil).value
    await model!.pendingPreview?.value
    #expect(model!.reel?.clips.count == names.count)
    // Peek and scrub every clip: five scrub players made, two evicted.
    for clip in model!.reel?.clips ?? [] {
      model!.select(clip.id, extend: false, toggle: false)
      for t in [0.5, 1.0, 1.5] {
        model!.peek(sourceTime: RationalTime(seconds: t, timescale: 600))
      }
      let end = ContinuousClock.now + .seconds(5)
      while model!.scrub.clipIDs.first != clip.id, ContinuousClock.now < end {
        try await Task.sleep(for: .milliseconds(10))
      }
    }
    #expect(model!.scrub.clipIDs.count == 3)
    model!.endPeek()
    model!.newReel()
    await model!.pendingPreview?.value
    // A second Reel, then the model itself goes.
    await model!.importURLs(Array(urls.prefix(2)), at: nil).value
    await model!.pendingPreview?.value
    model = nil

    let end = ContinuousClock.now + .seconds(10)
    while deaths.total.load(ordering: .relaxed) < made.total.load(ordering: .relaxed), ContinuousClock.now < end {
      try await Task.sleep(for: .milliseconds(50))
    }
    let total = deaths.total.load(ordering: .relaxed), onMain = deaths.onMain.load(ordering: .relaxed)
    print("assets: \(made.total.load(ordering: .relaxed)) handed out, \(total) freed, \(onMain) on main")
    #expect(onMain == 0, "\(onMain) AVURLAssets freed on the main thread")
  }
}
